def test_us1_pipeline_end_to_end(
    sample_audio_file,
    output_video_path,
    timestamp_map_path,
    cleanup_outputs,
):
    """T064: Test complete pipeline processes audio file to synchronized video.

    Validates that the entire pipeline orchestration works:
    1. Filename parsing
    2. Audio loading and conversion
    3. Hebrew text retrieval from Sefaria
    4. Forced alignment with aeneas
    5. Video rendering with static text overlay
    6. Output file generation
    """
    # Execute pipeline via CLI
    result = subprocess.run(
        ["uv", "run", "torah-sync", "process", str(sample_audio_file)],
        capture_output=True,
        text=True,
        timeout=120,  # 2 minute timeout
    )

    # Verify successful execution
    assert result.returncode == 0, (
        f"Pipeline failed with exit code {result.returncode}\n"
        f"STDOUT: {result.stdout}\n"
        f"STDERR: {result.stderr}"
    )

    # Verify output video was created
    assert output_video_path.exists(), (
        f"Output video not created at {output_video_path}\n"
        f"Pipeline output: {result.stdout}"
    )

    # Verify timestamp map was created
    assert timestamp_map_path.exists(), (
        f"Timestamp map not created at {timestamp_map_path}\n"
        f"Pipeline output: {result.stdout}"
    )

    # Verify timestamp map is valid JSON
    with open(timestamp_map_path) as f:
        timestamp_data = json.load(f)

    assert "verse_timestamps" in timestamp_data, "Timestamp map missing verse_timestamps"
    assert len(timestamp_data["verse_timestamps"]) > 0, "Timestamp map has no verses"

    # Verify CLI output contains success message
    assert "Video created successfully" in result.stdout, (
        f"Success message not in output: {result.stdout}"
    )


def test_us1_output_video_format_and_dimensions(output_video_path):
    """T065: Verify output video has correct format, resolution, and duration.

    Validates:
    - Video file format is MP4
    - Resolution is 640x360 (as configured)
    - Duration matches audio duration
    - Video codec is H.264
    """
    assert output_video_path.exists(), f"Output video not found: {output_video_path}"

    # Load video with moviepy
    video = VideoFileClip(str(output_video_path))

    try:
        # Verify resolution
        width, height = video.size
        assert width == 640, f"Expected width 640, got {width}"
        assert height == 360, f"Expected height 360, got {height}"

        # Verify duration is reasonable (Haazinu Rishon is ~70 seconds)
        assert video.duration > 60, f"Video too short: {video.duration}s"
        assert video.duration < 120, f"Video too long: {video.duration}s"

        # Verify FPS
        assert video.fps > 0, f"Invalid FPS: {video.fps}"

        # Verify file extension
        assert output_video_path.suffix == ".mp4", (
            f"Expected .mp4 extension, got {output_video_path.suffix}"
        )

        # Verify file size is reasonable (not empty, not too large)
        file_size_mb = output_video_path.stat().st_size / (1024 * 1024)
        assert file_size_mb > 0.5, f"Video file too small: {file_size_mb:.2f}MB"
        assert file_size_mb < 10, f"Video file too large: {file_size_mb:.2f}MB"

    finally:
        video.close()


def test_us1_verse_timing_accuracy(timestamp_map_path, output_video_path):
    """T066: Verify verse highlighting timing is accurate within 0.5s.

    Validates:
    - Timestamp map has monotonically increasing timestamps
    - No gaps larger than 5 seconds between verses
    - Timestamps align with actual video duration
    - Sample timestamp checks for known verse transitions
    """
    assert timestamp_map_path.exists(), f"Timestamp map not found: {timestamp_map_path}"

    with open(timestamp_map_path) as f:
        timestamp_data = json.load(f)

    verses = timestamp_data["verse_timestamps"]
    assert len(verses) >= 6, f"Expected at least 6 verses, got {len(verses)}"

    # Verify monotonic increase
    for i in range(len(verses) - 1):
        current_end = verses[i]["end_time"]
        next_start = verses[i + 1]["start_time"]

        assert next_start >= current_end, (
            f"Non-monotonic timestamps: verse {i} ends at {current_end}s, "
            f"but verse {i+1} starts at {next_start}s"
        )

        # Verify no large gaps (allowing for natural pauses)
        gap = next_start - current_end
        assert gap <= 5.0, (
            f"Large gap ({gap:.2f}s) between verse {i} and {i+1}"
        )

    # Verify first verse starts near beginning
    assert verses[0]["start_time"] < 2.0, (
        f"First verse starts too late: {verses[0]['start_time']}s"
    )

    # Load video to verify total duration alignment
    video = VideoFileClip(str(output_video_path))
    try:
        video_duration = video.duration
        last_verse_end = verses[-1]["end_time"]

        # Last verse should end before video end (video shows static text throughout)
        # The video duration matches the audio, but the last verse timestamp
        # marks where the verse text ends, not where the video ends
        assert last_verse_end <= video_duration, (
            f"Last verse end time ({last_verse_end}s) exceeds "
            f"video duration ({video_duration}s)"
        )

        # Verify last verse is within reasonable range of video duration
        # (allowing for intro and natural spacing)
        assert last_verse_end >= video_duration * 0.5, (
            f"Last verse ends too early ({last_verse_end}s) relative to "
            f"video duration ({video_duration}s)"
        )
    finally:
        video.close()

    # Verify each verse has valid reference
    for i, verse in enumerate(verses):
        assert "reference" in verse, f"Verse {i} missing reference"
        assert "start_time" in verse, f"Verse {i} missing start_time"
        assert "end_time" in verse, f"Verse {i} missing end_time"

        # Verify reasonable verse duration (0.1s to 30s)
        # Allow for short intros and natural verse length variation
        duration = verse["end_time"] - verse["start_time"]
        assert 0.1 <= duration <= 30, (
            f"Verse {i} ({verse['reference']}) has unreasonable duration: {duration:.2f}s"
        )


def test_us1_hebrew_text_readability(output_video_path):
    """T067: Verify Hebrew text with diacritics is readable in rendered frames.

    Validates:
    - Text is visible (not completely black)
    - Text contains multiple unique pixel values (not uniform color)
    - Frames are not blank (have content)
    - Multiple frames show consistent text rendering

    Note: This is a basic visual validation. Full character recognition
    would require OCR, which is beyond scope. We validate that text
    rendering produces visible, non-blank output.
    """
    assert output_video_path.exists(), f"Output video not found: {output_video_path}"

    video = VideoFileClip(str(output_video_path))

    try:
        # Extract frames at different points in video
        sample_times = [
            1.0,  # Early frame (likely first verse)
            video.duration / 2,  # Middle frame
            video.duration - 2.0,  # Late frame
        ]

        for sample_time in sample_times:
            # Get frame as numpy array
            frame = video.get_frame(sample_time)

            # Convert to PIL Image for analysis
            img = Image.fromarray(frame)

            # Verify frame is not completely black
            # (text should have white pixels on black background)
            extrema = img.convert("L").getextrema()
            min_brightness, max_brightness = extrema

            assert max_brightness > 200, (
                f"Frame at {sample_time}s too dark - text may not be visible. "
                f"Max brightness: {max_brightness}"
            )

            # Verify frame has contrast (not uniform color)
            assert max_brightness - min_brightness > 100, (
                f"Frame at {sample_time}s has low contrast. "
                f"Range: {min_brightness}-{max_brightness}"
            )

            # Count unique colors (should be many for anti-aliased text)
            unique_colors = len(img.getcolors(maxcolors=10000))
            assert unique_colors > 10, (
                f"Frame at {sample_time}s has too few colors ({unique_colors}). "
                f"Text may not be rendering correctly."
            )

            # Verify significant white content (text should occupy frame)
            # Static text rendering typically uses 2-15% of pixels for Hebrew text
            pixels = list(img.convert("L").getdata())
            white_pixels = sum(1 for p in pixels if p > 200)
            white_percentage = (white_pixels / len(pixels)) * 100

            assert 1 <= white_percentage <= 50, (
                f"Frame at {sample_time}s has unusual white content: {white_percentage:.1f}%. "
                f"Expected 1-50% for readable text (lower end for static text with margins)."
            )

    finally:
        video.close()


